\begin{definition}[Lumped heat-flow law, Eq.\ (4)]
\label{def:IPhO2026Problems_problem_IPhO_2026_4_C_7:LumpedHeatFlowLaw}
\lean{IPhO2026.Problem4.C7.LumpedHeatFlowLaw}
